import React from "react";
import { Link } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

export default function Register() {
  return (
    <div
      className="min-vh-100 d-flex align-items-center justify-content-center"
      style={{
        background: "linear-gradient(135deg, #fdf6ec, #f7efe5)",
      }}
    >
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-6 col-lg-4">
            <div className="card border-0 shadow-lg rounded-4 p-4">
              <div className="text-center mb-4">
                <h3 className="fw-bold text-brown">
                  Create Account 🌰
                </h3>
                <p className="text-muted mb-0">
                  Join us for premium quality dry fruits
                </p>
              </div>

              <form>
                <div className="mb-3">
                  <label className="form-label fw-semibold">
                    Full Name
                  </label>
                  <input
                    type="text"
                    className="form-control rounded-3"
                    placeholder="Your full name"
                  />
                </div>

                <div className="mb-3">
                  <label className="form-label fw-semibold">
                    Email Address
                  </label>
                  <input
                    type="email"
                    className="form-control rounded-3"
                    placeholder="you@email.com"
                  />
                </div>

                <div className="mb-3">
                  <label className="form-label fw-semibold">
                    Password
                  </label>
                  <input
                    type="password"
                    className="form-control rounded-3"
                    placeholder="Create a strong password"
                  />
                </div>

                <div className="mb-4">
                  <label className="form-label fw-semibold">
                    Confirm Password
                  </label>
                  <input
                    type="password"
                    className="form-control rounded-3"
                    placeholder="Re-enter password"
                  />
                </div>

                <button
                  type="submit"
                  className="btn w-100 py-2 fw-semibold rounded-3"
                  style={{
                    backgroundColor: "#8b5e3c",
                    color: "#fff",
                  }}
                >
                  Register
                </button>

                <p className="text-center mt-4 mb-0">
                  Already have an account?{" "}
                  <Link
                    to="/login"
                    className="text-brown fw-semibold text-decoration-none"
                  >
                    Login
                  </Link>
                </p>
              </form>
            </div>
          </div>
        </div>
      </div>

      {/* Theme Styles */}
      <style>
        {`
          .text-brown {
            color: #8b5e3c;
          }

          .form-control:focus {
            border-color: #8b5e3c;
            box-shadow: 0 0 0 0.2rem rgba(139, 94, 60, 0.25);
          }

          .card {
            animation: fadeInUp 0.6s ease;
          }

          @keyframes fadeInUp {
            from {
              opacity: 0;
              transform: translateY(20px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
        `}
      </style>
    </div>
  );
}
